from lib import *
S = SS('v2')
steps = [
    step("先看最坏的情形:C 完全不可用,一直回 503。client 发 20 个请求,每一层都“失败就重试,总共试 3 次”,没有退避、没有预算。没有重试层:C 收到 20 次调用,每个请求 1 次。1 层:60 次,每个请求 3 次。2 层:180 次,9 次。3 层:540 次,27 次。4 层:1620 次,81 次。每多一层,C 收到的调用就乘以 3,正好是 3 的层数次方。每一层单独看都只是多试 2 次,合起来是 3 的 L 次方。", t=tl(S(1)), mark=lidx(S(1), '3 层各试 3 次', '4 层各试 3 次'), done=lidx(S(1), '没有重试层', '1 层各试 3 次', '2 层各试 3 次'), b=bars([['0 层:每个请求', 1, '1'], ['1 层:每个请求', 3, '3'], ['2 层:每个请求', 9, '9'], ['3 层:每个请求', 27, '27'], ['4 层:每个请求', 81, '81']], 81, cur=[0, 1, 2], mark=[3, 4]), kv=KV([['1 层', 'C 收到 3 次 / 请求'], ['3 层', 'C 收到 27 次 / 请求'], ['4 层', 'C 收到 81 次 / 请求']], ['4 层'])),
    step("C 偶发失败时(每次调用独立地以概率 p 返回 503),3 层各试 3 次,每种 p 发 600 个请求。公式:一层的失败概率是下一层的三次方,一层的平均尝试次数是 1 + f + f²,各层相乘。p = 10%:C 每个请求收到 1.11 次(公式 1.11),client 成功 100.0%。p = 30%:1.45 次(公式 1.43),成功 100.0%(单次调用成功率只有 70%)。p = 50%:2.06 次(公式 2.00),100.0%。p = 90%:9.88 次(公式 9.42),成功 92.8%(公式 94.2%)。失败率低时重试几乎不增加负载就把成功率拉到 100%;失败率越高放大越大,p = 90% 时 C 要多接 9 倍多的调用,成功率仍然只有 92.8%。", t=tl(S(2)), mark=lidx(S(2), '90%'), done=lidx(S(2), '10%', '30%', '50%'), b=bars([['p=10% 每个请求的调用', 1.11, '1.11'], ['p=30%', 1.45, '1.45'], ['p=50%', 2.06, '2.06'], ['p=90%', 9.88, '9.88(公式 9.42)']], 9.88, done=[0, 1, 2], mark=[3]), kv=KV([['p = 30%', '单次成功 70% → 3 层后 100%'], ['p = 90%', 'C 收到 9.88 次 / 请求,成功 92.8%'], ['实测 vs 公式', '1.11 / 1.45 / 2.06 / 9.88 对 1.11 / 1.43 / 2.00 / 9.42']], ['p = 90%'])),
    step("再看 C 容量有限时。C 同时最多处理 4 个请求、每个 20 ms(容量 200/s),client 以 120/s 发 8 秒,第 2 到 3.5 秒 C 的处理时间变成 3 倍(容量约 67/s)。没有重试层:C 每秒都收到 120 次调用;第 2 秒 client 成功率 48%,第 3 秒 71%,第 4 秒回到 99%。3 层各试 3 次:C 每秒收到 120、155、1987、1202、120、120、120、127 次,触发那一秒是平时的 16 倍多;client 成功率 100%、99%、49%、73%、100%、100%、100%、100%。重试没有把成功率变高(第 2 秒 49% 对 48%),只是让 C 多收了十几倍的调用;因为是同步重试,触发结束后下一秒就恢复了。负载升到 160/s 时发请求的 Python 进程自己撑不住,那一档的数字不可信,没有放进来。", t=tl(S(3)), mark=lidx(S(3), '3 层各试 3 次'), done=lidx(S(3), '没有重试层'), b=bars([['无重试:触发那秒 C 收到', 120, '120'], ['3 层×3:触发那秒 C 收到', 1987, '1987'], ['无重试:触发那秒成功率 %', 48, '48%'], ['3 层×3:触发那秒成功率 %', 49, '49%']], 1987, done=[0, 2], mark=[1, 3]), kv=KV([['触发那秒 C 收到', '120 对 1987(16 倍)'], ['client 成功率', '48% 对 49%,重试没帮上忙'], ['恢复', '触发结束后的下一秒']], ['触发那秒 C 收到'])),
    step("网关再加一层。client → nginx(两个上游 A1、A2)→ A(失败就对 C 试 3 次)→ C(一直 503),每种配置 20 个请求。nginx 默认 proxy_next_upstream(error timeout)不会因 503 换上游:client 试 1 次时 C 收到 60 次(每个请求 3 次),client 试 3 次时 180 次(9 次)。加上 http_503 并保持上游默认的 max_fails=1:C 一共只收到 9 次(0.5 次 / 请求),client 看到 1 个 503 和 19 个 502;nginx 把每个 503 记成一次失败,把两个上游都摘掉,之后的请求由 nginx 自己回 502(error log:no live upstreams)。加上 http_503 并设 max_fails=0:client 试 1 次时 120 次(6 次 / 请求),client 试 3 次时 360 次(18 次 / 请求)。3 × 2 × 3 = 18,各层的重试次数是相乘的。", t=tl(S(4)), mark=lidx(S(4), 'max_fails=0'), done=lidx(S(4), '默认  ', 'max_fails=1'), b=bars([['client 1 / nginx 默认', 3, '3 次 / 请求'], ['client 3 / nginx 默认', 9, '9'], ['client 1 / http_503 + max_fails=0', 6, '6'], ['client 3 / http_503 + max_fails=0', 18, '18']], 18, cur=[0, 1], mark=[2, 3]), kv=KV([['默认 max_fails=1 + http_503', '上游被摘掉,19 个 502,C 只收到 9 次'], ['max_fails=0 + http_503', 'client 3 × nginx 2 × 服务 3 = 18'], ['nginx 默认', '不因 503 换上游,9 次 / 请求']], ['max_fails=0 + http_503'])),
]
A = mkartv('v2', 2, '微服务,弹性,重试,重试风暴,nginx,真实验证,动画演示',
    '实测重试的放大:C 完全不可用时每多一层“试 3 次”C 收到的调用乘以 3(4 层 81 倍);C 偶发失败 90% 时 3 层各试 3 次 C 要多接 9.88 倍;容量有限时触发那一秒 C 收到 1987 次对 120 次而成功率没变;nginx 加 http_503 后 client 3 × nginx 2 × 服务 3 = 18 倍。',
    '三层各重试三次,最底下的服务到底会收到多少请求?重试什么时候有用,什么时候只是添乱?加上网关的 proxy_next_upstream 又会怎样?这篇用本机起的小服务和 nginx,把放大倍数量出来,和公式对照。',
    [('81 倍', '4 层各试 3 次、C 完全不可用时,每个 client 请求让 C 收到的调用数(3 的 4 次方)'), ('1987 对 120', '容量有限的 C 在处理变慢的那一秒收到的调用数:3 层各试 3 次 对 没有重试层(成功率 49% 对 48%)'), ('18 倍', 'client 试 3 次 × nginx 换 2 个上游 × 服务试 3 次时,每个 client 请求让 C 收到的调用数')],
    [('层数相乘', '<p>每一层单独看只多试 2 次,合起来是 3 的层数次方;C 完全不可用时每多一层乘 3。</p>'),
     ('失败率与放大', '<p>失败率低时重试几乎不增加负载就把成功率拉到 100%;失败率越高放大越大,而这时 C 最撑不住。</p>'),
     ('容量有限时的放大', '<p>C 容量降低的那一秒,重试把 C 收到的调用乘了十几倍,成功率却没有提高。</p>'),
     ('网关的重试', '<p>nginx 的 proxy_next_upstream 又乘一层;加上 http_503 还会触发上游被摘除,出现 nginx 自己回的 502。</p>')],
    steps,
    [ENV_V + '。本篇的服务是 Python 3.14 http.server(线程化)在本进程里起的,C 的失败用带种子的随机数按概率注入;网关是 Homebrew 的 nginx 1.31.6;client 对同一端口复用 keep-alive 连接(否则几万次短连接会把本机临时端口用光,出现大量连接错误);实验里连接类错误 0 次',
     '没有验证:负载更高(160/s)的情形——发请求的这个 Python 进程自己撑不住(大量连接错误),那一档的数字不可信,没有放进文章;异步重试(重试请求在触发结束后继续堆积)导致的持续过载,这里的重试是同步的,触发结束后下一秒就恢复了;gRPC、Envoy 等其他代理的重试默认值;真实网络上的延迟'],
    '重试的放大效应')
